test("rounded cached PCM tails never overlap the next decode window", async () => {
 ranges.length=0;interrupt=undefined;
 const result=await collectTakeAudioEvidence({
  editor:{scenes:{getActiveScene:()=>({tracks:{main:{elements:[]}}})},media:{getAssets:()=>[{id:'voice',url:'http://local/source'}]}} as any,
  elementIds:['podcast-audio:0:6:0'],sourceClips:[{id:'podcast-audio:0:6:0',type:'audio',mediaId:'voice',startTime:0,duration:61*120000,trimStart:7616049,trimEnd:0,params:{audioSyncOffset:0}}] as any,
  signal:new AbortController().signal,boundedFrames:true,
  checkpoint:{key:'fractional-source-clock',store:{read:async({duration}:any)=>[{start:0,end:duration,rms:.1,peak:.2,zeroCrossingRate:0}],write:async()=>{throw Error('Cached audio was decoded again');}}},
 });
 expect(ranges).toHaveLength(0);
 const frames=result[0].frames;expect(frames).toHaveLength(3);
 for(let i=1;i<frames.length;i++)expect(frames[i].start).toBeGreaterThanOrEqual(frames[i-1].end-1e-8);
 expect(frames.at(-1)!.end).toBeLessThanOrEqual(61+1e-8);
});
EOF
